import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val arr = scanner.next().toCharArray()
    val brr = scanner.next().toCharArray()
    var ans = 0
    val n = arr.size
    for (i in 0 until n) {
        for (j in i until n) {
            var count = 0
            for (k in 0 until n) {
                if (k < i || k > j) {
                    if (count < brr.size) {
                        if (arr[k] == brr[count]) {
                            count++
                        }
                    } else {
                        break
                    }
                }
            }
            if (count == brr.size) {
                if (ans < j - i + 1) {
                    ans = j - i + 1
                }
            }
        }
    }
    println(ans)
}

